mapper.select:
select o.id, customer.phone as customer_phone, customer.customer_name, o.order_no, o.order_type, o.original_price, o.premium_price, o.user_discount_amount, o.voucher_id, o.voucher_amount, o.coupon_id, o.coupon_amount, o.final_pay_amount, o.balance_pay_amount, o.online_pay_amount, o.online_pay_type, o.online_pay_serial_number, o.pay_time, o.order_status, o.create_by, o.create_by_id, o.create_time, o.update_by, o.update_by_id, o.update_time, o.rewards_type, o.recharge_name, o.recharge_id, o.rewards_amount, o.rewards_time, o.network_product_id as network_product_id, o.network_day as networkDay, o.network_value_id as networkValueId, t3.is_bandwidth_display, CASE WHEN o.bandwidth_all IS NULL THEN t2.bandwidth ELSE o.bandwidth_all END as bandwidth, CASE WHEN o.network_count_all IS NULL THEN t2.network_count ELSE o.network_count_all END as networkCount, CASE WHEN o.ip_count_all IS NULL THEN t2.ip_count ELSE o.ip_count_all END as ipCount
from sys_order o left join sys_customer customer on o.create_by_id = customer.id left join sys_customer_ecs_work t on o.id = t.order_id left join sys_network_value t2 on o.network_value_id = t2.id left join sys_network_product t3 on t2.product_id = t3.id
where o.del_flag = 0
and t.id is null
and o.order_no like concat('%',#{orderNo},'%')
and o.id = #{orderId}
and o.order_type = #{orderType}
and t2.del_flag = 0 and o.order_type in (3,4,5)
and o.order_status = #{orderStatus}
and o.recharge_id = #{rechargeId}
and o.create_by_id = #{customerId}
and o.create_time >= #{startTime}
and o.create_time <= #{endTime}
and (customer.phone like concat('%',#{customerInfoQueryKey},'%') or customer.customer_name like concat('%',#{customerInfoQueryKey},'%'))
and t2.agi_customer_name like concat('%',#{agiCustomerName},'%')
and t3.name like concat('%',#{productName},'%')
and t2.bandwidth = #{bandwidth}
and t2.actual_status = #{actualStatus}
and t2.actual_status = #{actualStatus}
and t2.actual_agi_expire_time >= #{actualAgiExpireStartTime}
and t2.actual_agi_expire_time <= #{actualAgiExpireEndTime}
and t2.actual_agi_open_time >= str_to_date(concat(#{actualAgiOpenStartTime}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
and t2.actual_agi_open_time <= str_to_date(concat(#{actualAgiOpenEndTime}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
and t2.mobile like concat('%',#{mobile},'%')
order by o.create_time desc

select o.*, e.`level` as `level`, c.customer_name as userName, c.phone as userPhone from sys_order o left join sys_extend e on o.create_by_id = e.user_id left join sys_customer c on e.user_id = c.id where 1 = 1
and c.customer_name like concat('%',#{name},'%')
and e.level = #{level}
and o.settlement_status = #{settlementStatus}
and o.pay_time >= #{startTime}
and o.pay_time <= #{endTime}
and (o.first_user_id = #{userId} or o.two_user_id = #{userId})
and o.order_status = 1
order by o.create_time desc

select o.id, customer.phone as customer_phone, customer.customer_name, o.order_no, o.order_type, o.original_price, o.premium_price, o.user_discount_amount, o.voucher_id, o.voucher_amount, o.coupon_id, o.coupon_amount, o.final_pay_amount, o.balance_pay_amount, o.online_pay_amount, o.online_pay_type, o.online_pay_serial_number, o.pay_time, o.order_status, o.create_by, o.create_by_id, o.create_time, o.update_by, o.update_by_id, o.update_time, o.rewards_type, o.recharge_name, o.recharge_id, o.rewards_amount, o.rewards_time, o.network_product_id as network_product_id, o.network_day as networkDay, o.network_value_id as networkValueId, t3.is_bandwidth_display from sys_order o left join sys_customer customer on o.create_by_id = customer.id left join sys_network_value t2 on o.network_value_id = t2.id left join sys_network_product t3 on t2.product_id = t3.id
where o.del_flag = 0
and o.order_no like concat('%',#{orderNo},'%')
and o.id = #{orderId}
and o.order_type = #{orderType}
and t2.del_flag = 0
and o.order_status = #{orderStatus}
and o.recharge_id = #{rechargeId}
and o.create_by_id = #{customerId}
and o.create_time >= #{startTime}
and o.create_time <= #{endTime}
and (customer.phone like concat('%',#{customerInfoQueryKey},'%') or customer.customer_name like concat('%',#{customerInfoQueryKey},'%'))
and t2.agi_customer_name like concat('%',#{agiCustomerName},'%')
and t3.name like concat('%',#{productName},'%')
and t2.bandwidth = #{bandwidth}
and t2.actual_status = #{actualStatus}
and t2.actual_agi_expire_time >= #{actualAgiExpireStartTime}
and t2.actual_agi_expire_time <= #{actualAgiExpireEndTime}
and t2.mobile like concat('%',#{mobile},'%')
and t2.email like concat('%',#{email},'%')
order by o.actual_agi_expire_time
